"""
    DESCRIPTION: clean extra info from music name
    INPUT: music_name (str)
    OUTPUT: music_name (str)
    """
def clean_music_name(music_name: Any) -> object {
    breaking_substring_list = [' (feat.', ' (with'];
    for substring in breaking_substring_list {
        if (substring in music_name) {
            breaking_point = music_name.find(substring);
            music_name = music_name[:breaking_point];
        }
    }
    return music_name;
}

"""
    method 2 recursively find the method
    # result: 73682
    """
def recursively_find_changes(s: Any, token: Any) -> object {
    if (len(token) == 1) {
        if ((s % token[0]) == 0) {
            return 1;
        } else {
            return 0;
        }
    } else {
        count = 0;
        for i in range(0, (int((s / token[0])) + 1)) {
            count = count + recursively_find_changes((s - (i * token[0])), token[1:]);
        }
        return count;
    }
}

